// CAN_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module CAN_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [5:0] c_cfg_brp,
  input logic [3:0] c_cfg_tseg1,
  input logic [2:0] c_cfg_tseg2,
  input logic [1:0] c_cfg_sjw,
  input logic [28:0] c_acc_code,
  input logic [28:0] c_acc_mask,
  input logic [63:0] c_tx_data,
  input logic [28:0] c_tx_id,
  input logic  c_tx_ide,
  input logic  c_tx_rtr,
  input logic [3:0] c_tx_dlc,
  input logic  c_tx_abort,
  input logic [63:0] c_rx_data,
  input logic [28:0] c_rx_id,
  input logic  c_rx_ide,
  input logic  c_rx_rtr,
  input logic [3:0] c_rx_dlc,
  input logic [8:0] c_tec,
  input logic [7:0] c_rec,
  input logic  c_err_passive,
  input logic  c_bus_off,
  input logic  c_tx_valid,
  input logic  c_tx_ready,
  input logic  c_rx_valid,
  input logic  c_tx_done,
  input logic  c_tx_aborted,
  input logic  c_arb_lost,
  input logic  c_err_bit,
  input logic  c_err_stuff,
  input logic  c_err_crc,
  input logic  c_err_form,
  input logic  c_err_ack
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 18;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:17];          // model of every stored word
  logic [13:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_TX;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_tx_done) m_set[0] = 1'b1;
    if (c_tx_aborted) m_set[1] = 1'b1;
    if (c_arb_lost) m_set[2] = 1'b1;
    if (c_err_bit) m_set[3] = 1'b1;
    if (c_err_stuff) m_set[4] = 1'b1;
    if (c_err_crc) m_set[5] = 1'b1;
    if (c_err_form) m_set[6] = 1'b1;
    if (c_err_ack) m_set[7] = 1'b1;
    if (c_err_passive) m_set[8] = 1'b1;
    if (c_bus_off) m_set[9] = 1'b1;
    if (m_state_TX && c_tx_ready) m_set[10] = 1'b1;
    if (m_wr && m_map && (m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11) && m_state_TX) m_set[11] = 1'b1;
    if (c_rx_valid && !m_state_RX) m_set[12] = 1'b1;
    if (c_rx_valid && m_state_RX && (m_rd && m_map && m_idx == 16)) m_set[12] = 1'b1;
    if (c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 16)) m_set[13] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h2941;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_TX <= 0;
      m_state_RX <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3FFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h1FFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 12) ? PWDATA & m_be & 32'h1 : 0;
      if (m_wr && m_map && m_idx == 8 && !m_state_TX) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9 && !m_state_TX) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10 && !m_state_TX) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFFFF;
      if (m_wr && m_map && m_idx == 11 && !m_state_TX) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 11 && !m_state_TX) m_state_TX <= 1;
      if (m_state_TX && c_tx_ready) m_state_TX <= 0;
      if (c_rx_valid && (!m_state_RX || (m_rd && m_map && m_idx == 16))) begin
        m_w[13] <= (32'(c_rx_data[31:0]) << 0);
        m_w[14] <= (32'(c_rx_data[63:32]) << 0);
        m_w[15] <= (32'(c_rx_id[28:0]) << 0) | (32'(c_rx_ide) << 29) | (32'(c_rx_rtr) << 30);
        m_w[16] <= (32'(c_rx_dlc[3:0]) << 0);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 16)) m_state_RX <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h43410200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX, m_state_TX});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return 0;
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return m_w[16];
      17: return (32'(c_tec) << 0) | (32'(c_rec) << 9) | (32'(c_err_passive) << 17) | (32'(c_bus_off) << 18);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][13:0] & m_w[2][13:0]))
  `SVA_INV(a_core_cfg_brp, c_cfg_brp == m_w[5][5:0])
  `SVA_INV(a_core_cfg_tseg1, c_cfg_tseg1 == m_w[5][9:6])
  `SVA_INV(a_core_cfg_tseg2, c_cfg_tseg2 == m_w[5][12:10])
  `SVA_INV(a_core_cfg_sjw, c_cfg_sjw == m_w[5][14:13])
  `SVA_INV(a_core_acc_code, c_acc_code == m_w[6][28:0])
  `SVA_INV(a_core_acc_mask, c_acc_mask == m_w[7][28:0])
  `SVA_INV(a_core_tx_data_31_0, c_tx_data[31:0] == m_w[8][31:0])
  `SVA_INV(a_core_tx_data_63_32, c_tx_data[63:32] == m_w[9][31:0])
  `SVA_INV(a_core_tx_id, c_tx_id == m_w[10][28:0])
  `SVA_INV(a_core_tx_ide, c_tx_ide == m_w[10][29:29])
  `SVA_INV(a_core_tx_rtr, c_tx_rtr == m_w[10][30:30])
  `SVA_INV(a_core_tx_dlc, c_tx_dlc == m_w[11][3:0])
  `SVA_INV(a_core_tx_abort, c_tx_abort == m_pulse_CMD[0])
  `SVA_INV(a_core_tx_valid, c_tx_valid == m_state_TX)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_brp == 6'h1 && c_cfg_tseg1 == 4'h5 && c_cfg_tseg2 == 3'h2 && c_cfg_sjw == 2'h1 && c_acc_code == 29'h0 && c_acc_mask == 29'h0 && c_tx_data[31:0] == 32'h0 && c_tx_data[63:32] == 32'h0 && c_tx_id == 29'h0 && c_tx_ide == 1'h0 && c_tx_rtr == 1'h0 && c_tx_dlc == 4'h0 && c_tx_abort == 1'h0 && !c_tx_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_BTR, m_rd && m_map && m_idx == 5)
  `FC(wr_BTR, m_wr && m_map && m_idx == 5)
  `FC(rd_ACC_CODE, m_rd && m_map && m_idx == 6)
  `FC(wr_ACC_CODE, m_wr && m_map && m_idx == 6)
  `FC(rd_ACC_MASK, m_rd && m_map && m_idx == 7)
  `FC(wr_ACC_MASK, m_wr && m_map && m_idx == 7)
  `FC(rd_TX0, m_rd && m_map && m_idx == 8)
  `FC(wr_TX0, m_wr && m_map && m_idx == 8)
  `FC(rd_TX1, m_rd && m_map && m_idx == 9)
  `FC(wr_TX1, m_wr && m_map && m_idx == 9)
  `FC(rd_TX2, m_rd && m_map && m_idx == 10)
  `FC(wr_TX2, m_wr && m_map && m_idx == 10)
  `FC(rd_TX3, m_rd && m_map && m_idx == 11)
  `FC(wr_TX3, m_wr && m_map && m_idx == 11)
  `FC(rd_CMD, m_rd && m_map && m_idx == 12)
  `FC(wr_CMD, m_wr && m_map && m_idx == 12)
  `FC(rd_RX0, m_rd && m_map && m_idx == 13)
  `FC(wr_RX0, m_wr && m_map && m_idx == 13)
  `FC(rd_RX1, m_rd && m_map && m_idx == 14)
  `FC(wr_RX1, m_wr && m_map && m_idx == 14)
  `FC(rd_RX2, m_rd && m_map && m_idx == 15)
  `FC(wr_RX2, m_wr && m_map && m_idx == 15)
  `FC(rd_RX3, m_rd && m_map && m_idx == 16)
  `FC(wr_RX3, m_wr && m_map && m_idx == 16)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 17)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 17)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_SENT_set, m_set[0])
  `FC(irq_SENT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_SENT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_SENT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ABORTED_set, m_set[1])
  `FC(irq_ABORTED_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ABORTED_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ABORTED_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ARB_LOST_set, m_set[2])
  `FC(irq_ARB_LOST_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ARB_LOST_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ARB_LOST_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ERR_BIT_set, m_set[3])
  `FC(irq_ERR_BIT_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ERR_BIT_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ERR_BIT_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_ERR_STUFF_set, m_set[4])
  `FC(irq_ERR_STUFF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_ERR_STUFF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_ERR_STUFF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_ERR_CRC_set, m_set[5])
  `FC(irq_ERR_CRC_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_ERR_CRC_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_ERR_CRC_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_ERR_FORM_set, m_set[6])
  `FC(irq_ERR_FORM_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_ERR_FORM_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_ERR_FORM_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_ERR_ACK_set, m_set[7])
  `FC(irq_ERR_ACK_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_ERR_ACK_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_ERR_ACK_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_ERR_PASSIVE_set, m_set[8])
  `FC(irq_ERR_PASSIVE_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_ERR_PASSIVE_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_ERR_PASSIVE_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_BUS_OFF_set, m_set[9])
  `FC(irq_BUS_OFF_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_BUS_OFF_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_BUS_OFF_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_TX_DONE_set, m_set[10])
  `FC(irq_TX_DONE_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_TX_DONE_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_TX_DONE_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(irq_TX_OVF_set, m_set[11])
  `FC(irq_TX_OVF_cleared, m_w[1][11] && m_wr && m_map && m_idx == 1 && PWDATA[11] && PSTRB[1])
  `FC(irq_TX_OVF_masked, m_w[1][11] && !m_w[2][11])
  `FC(irq_TX_OVF_drives_pin, m_w[1][11] && m_w[2][11] && irq)
  `FC(irq_RX_AVAIL_set, m_set[12])
  `FC(irq_RX_AVAIL_cleared, m_w[1][12] && m_wr && m_map && m_idx == 1 && PWDATA[12] && PSTRB[1])
  `FC(irq_RX_AVAIL_masked, m_w[1][12] && !m_w[2][12])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][12] && m_w[2][12] && irq)
  `FC(irq_RX_OVF_set, m_set[13])
  `FC(irq_RX_OVF_cleared, m_w[1][13] && m_wr && m_map && m_idx == 1 && PWDATA[13] && PSTRB[1])
  `FC(irq_RX_OVF_masked, m_w[1][13] && !m_w[2][13])
  `FC(irq_RX_OVF_drives_pin, m_w[1][13] && m_w[2][13] && irq)
  `FC(cmd_tx_abort, m_pulse_CMD[0])
  `FC(TX_handshake, m_state_TX && c_tx_ready)
  `FC(TX_backpressure, m_state_TX && !c_tx_ready)
  `FC(TX_write_while_full, m_wr && m_map && m_idx == 11 && m_state_TX)
  `FC(RX_capture, c_rx_valid && !m_state_RX)
  `FC(RX_overflow, c_rx_valid && m_state_RX && !(m_rd && m_map && m_idx == 16))
  `FC(RX_pop, m_rd && m_map && m_idx == 16 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 16 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rx_valid && m_state_RX && m_rd && m_map && m_idx == 16)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind CAN_apb CAN_apb_sva u_apb_sva (.*);
